\prod_{i=1}^n f(x_i;\theta) &= \prod_{i=1}^n \theta^{x_i} (1-\theta)^{1-x_i} \\

&= \theta^{\sum x_i} (1-\theta)^{n-\sum x_i} \\

&= \underset{ = \theta^{\sum x_i} (1-\theta)^{n-\sum x_i}} {\boxed{g(\sum x_i ; \theta)}} \underset{=1}{\boxed{h(x_1, \cdots, x_n)}}

\end{aligned}
